'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { startAssessment, submitAssessment } from '../../services/api';
import QuestionCard from '../../components/Assessment/QuestionCard';
import ProgressBar from '../../components/Assessment/ProgressBar';

export default function AssessmentPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [questions, setQuestions] = useState([]);
    const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    const [answers, setAnswers] = useState([]);
    const [setId, setSetId] = useState(null);

    // Temporary User ID generator or retrieval
    const getUserId = () => {
        let uid = localStorage.getItem('disc_user_id');
        if (!uid) {
            uid = 'user_' + Math.random().toString(36).substr(2, 9);
            localStorage.setItem('disc_user_id', uid);
        }
        return uid;
    };

    useEffect(() => {
        const fetchQuestions = async () => {
            try {
                const userId = getUserId();
                const data = await startAssessment(userId);
                if (data && data.questions) {
                    setQuestions(data.questions);
                    setSetId(data.setId);
                }
            } catch (error) {
                console.error("Failed to load questions", error);
            } finally {
                setLoading(false);
            }
        };
        fetchQuestions();
    }, []);

    const handleAnswer = async (type) => {
        // If user clicked "Describes Me", type is "D"/"I"/"S"/"C".
        // If "Not Me", type is null.

        if (type) {
            const currentQ = questions[currentQuestionIndex];
            setAnswers(prev => [...prev, { qId: currentQ.qId, answer: type }]);
        }

        if (currentQuestionIndex < questions.length - 1) {
            setCurrentQuestionIndex(prev => prev + 1);
        } else {
            // Finished
            setLoading(true);
            try {
                const userId = getUserId();
                await submitAssessment(userId, setId, answers);
                router.push('/results');
            } catch (error) {
                console.error("Failed to submit", error);
                setLoading(false);
            }
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-black text-white">
                <div className="animate-pulse flex flex-col items-center">
                    <div className="h-12 w-12 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-cyan-400 font-mono">Loading System...</p>
                </div>
            </div>
        );
    }

    return (
        <main className="min-h-screen flex flex-col items-center justify-center p-4 bg-black overflow-hidden relative">
            {/* Background Particles/Glow - handled by globals but we can add specific emphasis here */}
            <div className="absolute top-0 left-0 w-full h-full overflow-hidden z-0 pointer-events-none">
                <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-purple-600/20 rounded-full blur-[100px]" />
                <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-cyan-600/20 rounded-full blur-[100px]" />
            </div>

            <div className="z-10 w-full max-w-4xl">
                <ProgressBar current={currentQuestionIndex + 1} total={questions.length} />

                {questions.length > 0 && (
                    <QuestionCard
                        question={questions[currentQuestionIndex]}
                        onAnswer={handleAnswer}
                    />
                )}
            </div>
        </main>
    );
}
